    void updatePackageProgress(){if(packageStatus==null)return;int label=packages.phase.equals("download")?R.string.models_downloading:packages.phase.equals("extract")?R.string.vp_extract:packages.phase.equals("validate")?R.string.vp_validate:packages.phase.equals("done")?R.string.vp_done:packages.phase.equals("deleted")?R.string.vp_deleted:packages.phase.equals("delete")?R.string.models_deleting:R.string.models_loading;String message=packages.phase.equals("failed")?packageError(packages.error):getString(label);packageStatus.setText(message);packageStatus.setTextColor(packages.phase.equals("failed")?RED:INK);boolean copying=packages.phase.equals("copy")||packages.phase.equals("download");packageBytes.setVisibility(copying?View.VISIBLE:View.GONE);packageBytes.setText(android.text.format.Formatter.formatFileSize(this,packages.transferred)+(packages.total>0?" / "+android.text.format.Formatter.formatFileSize(this,packages.total):""));packageProgress.setVisibility(packages.busy?View.VISIBLE:View.GONE);packageProgress.setIndeterminate(!copying||packages.total<=0);if(copying&&packages.total>0)packageProgress.setProgress((int)Math.min(100,packages.transferred*100/packages.total));cancelImport.setVisibility(packages.phase.equals("delete")?View.GONE:View.VISIBLE);((TextView)cancelImport).setText(getString(packages.busy?R.string.ui_94:R.string.ui_11));}
    String packageError(String code){int resource=code.equals("model_graph")?R.string.vp_error_graph:code.equals("language")?R.string.vp_error_language:code.equals("unknown_language")?R.string.vp_error_unknown:code.equals("incomplete")?R.string.vp_error_incomplete:code.equals("duplicate")?R.string.vp_error_duplicate:code.equals("large")||code.equals("storage")?R.string.vp_error_storage:code.equals("url")?R.string.vp_error_url:code.equals("cancelled")?R.string.vp_cancelled:code.equals("download")?R.string.speech_download_failed:code.equals("in_use")?R.string.vp_in_use:R.string.vp_error_invalid;return getString(resource);}
    void choosePackage(String language){if(packages.busy)return;stopPreview();importLanguage=language;Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);try{startActivityForResult(intent,702);}catch(ActivityNotFoundException error){Toast.makeText(this,R.string.vp_error_invalid,Toast.LENGTH_LONG).show();}}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=702||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();boolean hadGrant=false;for(android.content.UriPermission grant:getContentResolver().getPersistedUriPermissions())if(grant.getUri().equals(uri)&&grant.isReadPermission())hadGrant=true;boolean acquired=false;try{getContentResolver().takePersistableUriPermission(uri,Intent.FLAG_GRANT_READ_URI_PERMISSION);acquired=true;}catch(SecurityException ignored){}packages.importUri("",uri,acquired&&!hadGrant);}
    void askAddress(String language){if(packages.busy)return;stopPreview();EditText input=new EditText(this);input.setTextSize(14);input.setSingleLine(true);input.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);input.setHint("https://…/voice.tar.bz2");LinearLayout box=column();box.setPadding(dp(22),dp(8),dp(22),0);box.addView(input);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(getString(R.string.vp_address)).setMessage(R.string.vp_error_url).setView(box).setNegativeButton(R.string.ui_94,null).setPositiveButton(R.string.models_download,null).create();dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setTextColor(RED);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String address=input.getText().toString();try{VoicePackages.address(address);}catch(Exception error){input.setError(getString(R.string.vp_error_url));return;}packages.download("",address);dialog.dismiss();});});dialog.show();}
